        //spacing class: neon-2_20_1-popover-popper-body
        'data-injection-spacing': toAttribute(props.dataInjectionSpacing),
        'data-is-labeled-widget': toAttribute(props.dataIsLabeledWidget),
        'data-constrain-popper': toAttribute(props.dataConstrainPopper),
